        '199|HOTEL LIFESTYLE HOLIDAYS|HOTEL LIFESTYLE HOLIDAYS|HOTEL|REPUBLICA DOMINICANA|PUERTO PLATA|ACTIVO|Sistema|2024-01-01 00:00:00|2024-01-01 00:00:00',
        '200|HOTEL GRAND PARADISE GOLDEN|HOTEL GRAND PARADISE GOLDEN|HOTEL|REPUBLICA DOMINICANA|PUERTO PLATA|ACTIVO|Sistema|2024-01-01 00:00:00|2024-01-01 00:00:00'
    ];
    producto_data TEXT[];
    producto_id INTEGER;
    producto_nombre TEXT;
    producto_nombre_original TEXT;
    producto_tipo TEXT;
    producto_pais TEXT;
    producto_direccion TEXT;
    producto_status TEXT;
    producto_registrado_por TEXT;
    producto_fecha_creado TIMESTAMP;
    producto_fecha_editado TIMESTAMP;
    contador INTEGER := 0;
BEGIN
    RAISE NOTICE '🔄 Iniciando actualización de productos...';
    
    -- Procesar cada producto
    FOREACH producto_data IN ARRAY productos_data
    LOOP
        -- Dividir la cadena por el delimitador |
        SELECT string_to_array(producto_data, '|') INTO producto_data;
        
        -- Extraer valores
        producto_id := producto_data[1]::INTEGER;
        producto_nombre := producto_data[2];
        producto_nombre_original := producto_data[3];
        producto_tipo := producto_data[4];
        producto_pais := producto_data[5];
        producto_direccion := producto_data[6];
        producto_status := producto_data[7];
        producto_registrado_por := producto_data[8];
        producto_fecha_creado := producto_data[9]::TIMESTAMP;
        producto_fecha_editado := producto_data[10]::TIMESTAMP;
        
        -- Verificar si el producto existe
        IF EXISTS (SELECT 1 FROM productos WHERE id = producto_id) THEN
            -- Actualizar producto existente
            UPDATE productos SET
                nombre_producto = producto_nombre,
                nombre_original = producto_nombre_original,
                tipo = producto_tipo,
                pais = producto_pais,
                direccion = producto_direccion,
                status = producto_status,
                registrado_por = producto_registrado_por,
                fecha_creado = producto_fecha_creado,
                fecha_editado = producto_fecha_editado,
                contactos = 'Contacto actualizado',
                comentarios = 'Producto actualizado por script'
            WHERE id = producto_id;
            
            RAISE NOTICE 'Producto actualizado: ID % - %', producto_id, producto_nombre;
        ELSE
            -- Insertar nuevo producto
            INSERT INTO productos (
                id, nombre_producto, nombre_original, tipo, pais, direccion, 
                status, registrado_por, fecha_creado, fecha_editado,
                contactos, comentarios
            ) VALUES (
                producto_id, producto_nombre, producto_nombre_original, producto_tipo, 
                producto_pais, producto_direccion, producto_status, producto_registrado_por, 
                producto_fecha_creado, producto_fecha_editado,
                'Contacto nuevo', 'Producto insertado por script'
            );
            
            RAISE NOTICE 'Producto insertado: ID % - %', producto_id, producto_nombre;
        END IF;
        
        contador := contador + 1;
        
        -- Mostrar progreso cada 25 productos
        IF contador % 25 = 0 THEN
            RAISE NOTICE '📊 Progreso: % productos procesados', contador;
        END IF;
    END LOOP;
    
    -- Actualizar la secuencia para que los próximos productos empiecen desde 357
    PERFORM setval('productos_id_seq', 356, true);
    
    RAISE NOTICE '✅ Proceso completado. Secuencia actualizada para próximo ID: 357';
    RAISE NOTICE '📊 Total de productos procesados: % (IDs 101-200)', contador;
END $$;

COMMIT;

-- Verificar el resultado
SELECT 
    COUNT(*) as total_productos,
    MIN(id) as id_minimo,
    MAX(id) as id_maximo,
    COUNT(CASE WHEN id BETWEEN 101 AND 200 THEN 1 END) as productos_nuevos_rango
FROM productos;

RAISE NOTICE '🔍 Verificación completada. Revise los resultados arriba.';
